31	// fanOutConcurrentUse 让全部调用在同一道闸机释放后同时进入 Use，尽量制造交叉；
32	// 返回与调用一一对应的结果，调用方按下标分组核对成功记录与冲突。
33	func fanOutConcurrentUse(s *Store, calls []concurrentUseCall) []concurrentUseResult {
34		results := make([]concurrentUseResult, len(calls))
35		var wg sync.WaitGroup
36		start := make(chan struct{})
37		for i, c := range calls {
38			wg.Add(1)
39			go func(i int, c concurrentUseCall) {
40				defer wg.Done()
41				<-start
42				results[i].usage, results[i].err = s.Use(c.usageID, c.commitID, c.quantity, c.now)
43			}(i, c)
44		}
45		close(start)
46		wg.Wait()
47		return results
48	}
49	
50	// identicalUseCalls 构造 n 个内容完全相同的使用调用；每个调用给不同但都处于
51	// 承诺有效期内的当前时刻，以证明当前时刻不属于绑定内容。
52	func identicalUseCalls(usageID, commitID string, quantity, n int) []concurrentUseCall {
53		calls := make([]concurrentUseCall, n)
54		for i := range calls {
55			calls[i] = concurrentUseCall{
56				usageID:  usageID,
57				commitID: commitID,
58				quantity: quantity,
59				now:      nowOK.Add(time.Duration(i) * time.Hour),
60			}
61		}
62		return calls
63	}
