171		success, conflict := 0, 0
172		for i, c := range calls {
173			r := results[i]
174			if c.commitID == winner {
175				if r.err != nil || r.usage != winningUsage {
176					t.Fatalf("winner-group call %d = %+v, err %v; want %+v", i, r.usage, r.err, winningUsage)
177				}
178				success++
179			} else {
180				if !errors.Is(r.err, ErrConflict) || r.usage != (Usage{}) {
181					t.Fatalf("loser-group call %d = %+v, err %v; want ErrConflict with empty result", i, r.usage, r.err)
182				}
183				conflict++
184			}
