432		if _, err := s.Use("u2", "c1", 1, nowOK); !errors.Is(err, ErrCommitmentClosed) {
433			t.Fatalf("use after cancel: got %v", err)
434		}
435	}
436	
437	func TestExpiryAutoReleasesAndBlocksUse(t *testing.T) {
438		s := newStore(t)
439		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
440			t.Fatalf("reserve: %v", err)
441		}
442		if _, err := s.Use("u1", "c1", 2, nowOK); err != nil {
443			t.Fatalf("use: %v", err)
444		}
445		// 到期时刻之前：仍有效，可使用。
446		if _, err := s.Use("u2", "c1", 1, expiryOK.Add(-time.Second)); err != nil {
447			t.Fatalf("use just before expiry: %v", err)
448		}
449		// 到期时刻：自动失效，余量释放，后续使用被拒。
450		if _, err := s.Use("u3", "c1", 1, expiryOK); !errors.Is(err, ErrCommitmentClosed) {
451			t.Fatalf("use at expiry: got %v", err)
452		}
453		st, _ := s.PartStatus("part1", expiryOK)
454		if st.ActiveOccupied != 0 || st.Committable != 7 {
455			t.Fatalf("expiry did not release: occupied=%d committable=%d", st.ActiveOccupied, st.Committable)
456		}
457		// 查询直接体现失效，无需清理。
458		view, _ := s.RequestView("r1", expiryOK)
459		found := false
460		for _, d := range view.Commitments {
461			if d.CommitmentID == "c1" {
462				found = true
463				if d.Status != CommitmentExpired {
464					t.Fatalf("status = %q, want expired", d.Status)
465				}
466				if d.UsedQuantity != 3 || d.RemainingQuantity != 2 {
467					t.Fatalf("detail: used=%d remaining=%d", d.UsedQuantity, d.RemainingQuantity)
468				}
469			}
470		}
471		if !found {
472			t.Fatal("commitment not found in request view")
473		}
474	}
475	
476	func TestRequestView(t *testing.T) {
477		s := newStore(t)
478		if _, err := s.Reserve("c2", "r1", "part1", 2, expiryOK, nowOK); err != nil {
479			t.Fatalf("reserve: %v", err)
480		}
481		if _, err := s.Reserve("c1", "r1", "part1", 3, expiryOK, nowOK); err != nil {
482			t.Fatalf("reserve: %v", err)
483		}
484		view, err := s.RequestView("r1", nowOK)
485		if err != nil {
486			t.Fatalf("request view: %v", err)
487		}
488		if !view.Eligibility.Eligible {
489			t.Fatalf("expected eligible: %+v", view.Eligibility)
490		}
491		if len(view.Commitments) != 2 {
492			t.Fatalf("commitments = %d, want 2", len(view.Commitments))
493		}
494		// 按承诺编号排序。
495		if view.Commitments[0].CommitmentID != "c1" || view.Commitments[1].CommitmentID != "c2" {
496			t.Fatalf("order = %s, %s", view.Commitments[0].CommitmentID, view.Commitments[1].CommitmentID)
497		}
498		d := view.Commitments[0]
499		if d.RequestID != "r1" || d.PartID != "part1" || d.OriginalQuantity != 3 ||
500			d.UsedQuantity != 0 || d.RemainingQuantity != 3 || d.Status != CommitmentActive {
501			t.Fatalf("bad detail: %+v", d)
502		}
503		// 未知请求。
504		if _, err := s.RequestView("rMissing", nowOK); !errors.Is(err, ErrNotFound) {
505			t.Fatalf("unknown request view: got %v", err)
506		}
507	}
508	
509	func TestPartStatusDetailsIncludeClosed(t *testing.T) {
510		s := newStore(t)
511		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
512			t.Fatalf("reserve: %v", err)
513		}
514		if _, err := s.Use("u1", "c1", 2, nowOK); err != nil {
515			t.Fatalf("use: %v", err)
516		}
517		if _, err := s.Cancel("c1", nowOK); err != nil {
518			t.Fatalf("cancel: %v", err)
519		}
520		if _, err := s.Reserve("c2", "r1", "part1", 3, expiryOK, nowOK); err != nil {
521			t.Fatalf("reserve c2: %v", err)
522		}
523		st, err := s.PartStatus("part1", nowOK)
524		if err != nil {
525			t.Fatalf("part status: %v", err)
526		}
527		// 实物 10 - 2 = 8；有效占用 3；可承诺 5。
528		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
529			t.Fatalf("stock: phys=%d occupied=%d committable=%d", st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
530		}
531		if len(st.Details) != 2 {
532			t.Fatalf("details = %d, want 2 (canceled record still traceable)", len(st.Details))
533		}
534		byID := map[string]CommitmentDetail{}
535		for _, d := range st.Details {
536			byID[d.CommitmentID] = d
537		}
538		d1 := byID["c1"]
539		if d1.Status != CommitmentCanceled || d1.UsedQuantity != 2 || d1.RemainingQuantity != 3 ||
540			d1.OriginalQuantity != 5 || d1.RequestID != "r1" {
541			t.Fatalf("canceled detail: %+v", d1)
542		}
543		d2 := byID["c2"]
544		if d2.Status != CommitmentActive || d2.RemainingQuantity != 3 {
545			t.Fatalf("active detail: %+v", d2)
546		}
547	}
548	
549	func TestConcurrentReservesDoNotOversell(t *testing.T) {
550		s := newStore(t)
551		const n = 30
552		var wg sync.WaitGroup
553		var mu sync.Mutex
554		success, failed := 0, 0
555		for i := 0; i < n; i++ {
556			wg.Add(1)
557			go func(i int) {
558				defer wg.Done()
559				_, err := s.Reserve(fmt.Sprintf("c%02d", i), "r1", "part1", 1, expiryOK, nowOK)
560				mu.Lock()
561				defer mu.Unlock()
562				if err == nil {
563					success++
564				} else if errors.Is(err, ErrInsufficientStock) {
565					failed++
566				} else {
567					t.Errorf("unexpected error: %v", err)
568				}
569			}(i)
570		}
571		wg.Wait()
572		if success != 10 || failed != 20 {
573			t.Fatalf("success=%d failed=%d, want 10/20", success, failed)
574		}
575		st, _ := s.PartStatus("part1", nowOK)
576		if st.ActiveOccupied != 10 || st.Committable != 0 || st.PhysicalRemaining != 10 {
577			t.Fatalf("after concurrency: phys=%d occupied=%d committable=%d", st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
578		}
579	}
580	
581	func TestConcurrentIdempotentReserveSameID(t *testing.T) {
582		s := newStore(t)
583		var wg sync.WaitGroup
584		results := make([]Commitment, 8)
585		errs := make([]error, 8)
586		for i := 0; i < 8; i++ {
587			wg.Add(1)
588			go func(i int) {
589				defer wg.Done()
590				results[i], errs[i] = s.Reserve("same", "r1", "part1", 1, expiryOK, nowOK)
591			}(i)
592		}
593		wg.Wait()
594		for i, err := range errs {
595			if err != nil {
596				t.Fatalf("goroutine %d: %v", i, err)
597			}
598			if results[i].ID != "same" || results[i].Quantity != 1 {
599				t.Fatalf("goroutine %d got %+v", i, results[i])
600			}
601		}
602		st, _ := s.PartStatus("part1", nowOK)
603		if st.ActiveOccupied != 1 {
604			t.Fatalf("same-id concurrent reserve occupied %d", st.ActiveOccupied)
605		}
606	}
607	
608	func TestConcurrentUsesDoNotExceedStock(t *testing.T) {
609		s := newStore(t)
610		if _, err := s.Reserve("c1", "r1", "part1", 10, expiryOK, nowOK); err != nil {
611			t.Fatalf("reserve: %v", err)
612		}
613		var wg sync.WaitGroup
614		var mu sync.Mutex
615		success, failed := 0, 0
616		for i := 0; i < 20; i++ {
617			wg.Add(1)
618			go func(i int) {
619				defer wg.Done()
620				_, err := s.Use(fmt.Sprintf("u%02d", i), "c1", 1, nowOK)
621				mu.Lock()
622				defer mu.Unlock()
623				if err == nil {
624					success++
625				} else if errors.Is(err, ErrUsageExceeded) || errors.Is(err, ErrCommitmentClosed) {
626					failed++
627				} else {
628					t.Errorf("unexpected error: %v", err)
629				}
630			}(i)
631		}
632		wg.Wait()
633		if success != 10 || failed != 10 {
634			t.Fatalf("use success=%d failed=%d, want 10/10", success, failed)
635		}
636		c, _ := s.Commitment("c1")
637		if c.Used != 10 || c.Unused() != 0 {
638			t.Fatalf("commitment: used=%d unused=%d", c.Used, c.Unused())
639		}
640		st, _ := s.PartStatus("part1", nowOK)
641		if st.PhysicalRemaining != 0 {
642			t.Fatalf("physical remaining = %d, want 0", st.PhysicalRemaining)
643		}
644	}
