// snapshotIsPrefix 判定快照 seen 是否只含 finished 中已成功的编号（重叠查询
// 可以看不到正在处理的领取；不能看到尚未成功的编号）。
func snapshotOnlyFinished(seen, finished map[string]int) bool {
	for id := range seen {
		if _, ok := finished[id]; !ok {
			return false
		}
	}
	return true
}

